/// <summary>
/// PricingAttribute of table <c>WHSInventTable</c> field ProdQty.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventTableProdQty extends UPSPricingAttributeWHSInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventTable, ProdQty);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::Real);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by ProdQty
    {
        if (! ret.in(wHSInventTable.ProdQty))
        {
            ret.add(wHSInventTable.ProdQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, ProdQty));
    qbr.value(queryValue(_value));
}
